<script>
import {onMount} from 'svelte';
let {title='',index=0}=$props();
let root,active=$state(false);
onMount(()=>{const observer=new IntersectionObserver(entries=>{active=entries[0].isIntersecting;},{threshold:.5});observer.observe(root);return()=>observer.disconnect();});
</script>
<div bind:this={root} class="project-title" class:active style={'--delay:'+(index*.4)+'s'}>
 <h3>{title}</h3>
 <div class="arrow-slot" aria-hidden="true">
  <svg class="magic-arrow" viewBox="0 0 110 36"><path class="trail" d="M24 18 H109"/><path class="shaft" d="M12 18 H92 M74 18 L88 8 M74 18 L88 28"/><path class="head" d="M3 18 L23 8 L18 18 L23 28 Z"/></svg>
  <span class="flash"></span><span class="ring first"></span><span class="ring second"></span>
  {#each Array.from({length:8},(_,i)=>i) as i}<i class="spark" style={'--angle:'+(i*45)+'deg'}></i>{/each}
 </div>
</div>
<style>
.project-title{position:relative;display:flex;align-items:center;gap:10px;min-height:48px;margin-bottom:12px;padding-right:5px;isolation:isolate}.project-title h3{flex:1;min-width:0;margin:0!important;overflow-wrap:break-word;line-height:1.4}.arrow-slot{position:relative;flex:0 0 70px;width:70px;height:40px}.magic-arrow{position:absolute;left:0;top:5px;width:77px;height:30px;overflow:visible;filter:drop-shadow(0 0 4px #b48bff);opacity:0;animation:arrow-flight 7s var(--delay) infinite both}.shaft{fill:none;stroke:#9173d6;stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round}.head{fill:#a88cf0;stroke:#f7f0ff;stroke-width:1}.trail{fill:none;stroke:#b99af1;stroke-width:2;stroke-linecap:round;stroke-dasharray:3 7;opacity:.55}.flash{position:absolute;left:-3px;top:15px;width:13px;height:13px;border-radius:50%;background:#fff2cb;box-shadow:0 0 18px 8px #bba0f677;animation:magic-flash 7s var(--delay) infinite both}.ring{position:absolute;left:-15px;top:3px;width:36px;height:36px;border:2px solid #b699ed;border-radius:50%;opacity:0;animation:magic-ring 7s var(--delay) infinite both}.second{border-style:dashed;border-color:#e2bd74;animation-name:magic-ring-two}.spark{position:absolute;left:3px;top:19px;width:4px;height:4px;border-radius:50%;background:#f0c782;box-shadow:0 0 8px #d1acff;animation:magic-spark 7s var(--delay) infinite both}.project-title h3{animation:title-enchant 7s var(--delay) infinite both}.magic-arrow,.flash,.ring,.spark,.project-title h3{animation-play-state:paused}.active .magic-arrow,.active .flash,.active .ring,.active .spark,.active h3{animation-play-state:running}@keyframes arrow-flight{0%,8%{opacity:0;transform:translateX(90px)}9%{opacity:1}21%{opacity:1;transform:translateX(0)}26%{transform:translateX(-3px);opacity:1}36%,100%{opacity:0;transform:translateX(-3px)}}@keyframes magic-flash{0%,20%{opacity:0;transform:scale(.2)}23%{opacity:1;transform:scale(1.5)}33%,100%{opacity:0;transform:scale(.4)}}@keyframes magic-ring{0%,20%{opacity:0;transform:scale(.2)}23%{opacity:.9;transform:scale(.5)}43%,100%{opacity:0;transform:scale(2.6)}}@keyframes magic-ring-two{0%,23%{opacity:0;transform:scale(.2) rotate(0)}26%{opacity:.8;transform:scale(.5)}47%,100%{opacity:0;transform:scale(2.2) rotate(120deg)}}@keyframes magic-spark{0%,20%{opacity:0;transform:rotate(var(--angle)) translateX(0)}24%{opacity:1}45%,100%{opacity:0;transform:rotate(var(--angle)) translateX(55px)}}@keyframes title-enchant{0%,20%,45%,100%{text-shadow:none;transform:translateX(0)}23%{text-shadow:0 0 14px #b894f1;transform:translateX(-2px)}27%{text-shadow:0 0 18px #d1b4ff;transform:translateX(1px)}32%{text-shadow:0 0 8px #c6a1ef;transform:translateX(0)}}@media(max-width:650px){.arrow-slot{flex-basis:55px;width:55px}.magic-arrow{width:63px}.project-title h3{font-size:20px}}@media(prefers-reduced-motion:reduce){.project-title h3,.magic-arrow,.flash,.ring,.spark{animation:none;transform:none}.magic-arrow{opacity:.7}.flash,.ring,.spark{display:none}}
</style>
